-- =============================================================
-- Costmatic — company for the seeded catalog (1150 products)
--
-- Fills products.company, which the catalog seeds leave empty. Run AFTER
-- migration 0016 (which adds the column) and after the two catalog seeds.
--
--   psql "$DATABASE_URL" -f supabase/seeds/company_backfill.sql
--
-- Company is who the shop ORDERS FROM (PepsiCo Pakistan); brand is what is on
-- the bottle (7up). The Products screen filters by company because that is how
-- an order is actually placed — one PepsiCo call covers Pepsi, 7up, Mirinda,
-- Dew and Sting together.
--
-- Only fills blanks, so anything typed by hand survives and this is re-runnable.
-- =============================================================

do $co$
declare v_it jsonb; v_n int := 0;
